   126	UA_StatusCode
   127	sendServiceFault(UA_Server *server, UA_SecureChannel *channel,
   128	                 UA_UInt32 requestId, UA_UInt32 requestHandle,
   129	                 UA_StatusCode statusCode) {
   130	    UA_EventLoop *el = server->config.eventLoop;
   131	
   132	    UA_ServiceFault response;
   133	    UA_ServiceFault_init(&response);
   134	    UA_ResponseHeader *responseHeader = &response.responseHeader;
   135	    responseHeader->requestHandle = requestHandle;
   136	    responseHeader->timestamp = el->dateTime_now(el);
   137	    responseHeader->serviceResult = statusCode;
   138	
   139	    UA_LOG_DEBUG(channel->securityPolicy->logger, UA_LOGCATEGORY_SERVER,
   140	                 "Sending response for RequestId %u with ServiceResult %s",
   141	                 (unsigned)requestId, UA_StatusCode_name(statusCode));
   142	
   143	    /* Send error message. Message type is MSG and not ERR, since we are on a
   144	     * SecureChannel! */
   145	    return UA_SecureChannel_sendMSG(channel, requestId, &response,
   146	                                    &UA_TYPES[UA_TYPES_SERVICEFAULT]);
   147	}
