   150	static UA_StatusCode
   151	decodeHeaderSendServiceFault(UA_Server *server, UA_SecureChannel *channel,
   152	                             const UA_ByteString *msg, size_t offset,
   153	                             const UA_DataType *responseType, UA_UInt32 requestId,
   154	                             UA_StatusCode error) {
   155	    UA_RequestHeader requestHeader;
   156	    UA_StatusCode retval =
   157	        UA_decodeBinaryInternal(msg, &offset, &requestHeader,
   158	                                &UA_TYPES[UA_TYPES_REQUESTHEADER], NULL);
   159	    if(retval != UA_STATUSCODE_GOOD)
   160	        return retval;
   161	    retval = sendServiceFault(server, channel, requestId,
   162	                              requestHeader.requestHandle, error);
   163	    UA_RequestHeader_clear(&requestHeader);
   164	    return retval;
   165	}
