   171	/* HEL -> Open up the connection */
   172	static UA_StatusCode
   173	processHEL(UA_Server *server, UA_SecureChannel *channel, const UA_ByteString *msg) {
   174	    UA_LOCK_ASSERT(&server->serviceMutex);
   175	
   176	    UA_ConnectionManager *cm = channel->connectionManager;
   177	    if(!cm || (channel->state != UA_SECURECHANNELSTATE_CONNECTED &&
   178	               channel->state != UA_SECURECHANNELSTATE_RHE_SENT))
   179	        return UA_STATUSCODE_BADINTERNALERROR;
   180	
   181	    size_t offset = 0; /* Go to the beginning of the TcpHelloMessage */
   182	    UA_TcpHelloMessage helloMessage;
   183	    UA_StatusCode retval =
   184	        UA_decodeBinaryInternal(msg, &offset, &helloMessage,
   185	                                &UA_TRANSPORT[UA_TRANSPORT_TCPHELLOMESSAGE], NULL);
   186	    if(retval != UA_STATUSCODE_GOOD)
   187	        return retval;
   188	
   189	    /* Currently not checked */
   190	    UA_String_copy(&helloMessage.endpointUrl, &channel->endpointUrl);
   191	    UA_String_clear(&helloMessage.endpointUrl);
   192	
   193	    /* Parameterize the connection. The TcpHelloMessage casts to a
   194	     * TcpAcknowledgeMessage. */
   195	    retval = UA_SecureChannel_processHELACK(channel,
   196	                                            (UA_TcpAcknowledgeMessage*)&helloMessage);
   197	    if(retval != UA_STATUSCODE_GOOD) {
   198	        UA_LOG_INFO_CHANNEL(server->config.logging, channel,
   199	                            "Error during the HEL/ACK handshake");
   200	        return retval;
   201	    }
   202	
   203	    /* Get the send buffer from the network layer */
   204	    UA_ByteString ack_msg;
   205	    UA_ByteString_init(&ack_msg);
   206	    retval = cm->allocNetworkBuffer(cm, channel->connectionId,
   207	                                    &ack_msg, channel->config.sendBufferSize);
   208	    if(retval != UA_STATUSCODE_GOOD)
   209	        return retval;
   210	
   211	    /* Build acknowledge response */
   212	    UA_TcpAcknowledgeMessage ackMessage;
   213	    ackMessage.protocolVersion = 0;
   214	    ackMessage.receiveBufferSize = channel->config.recvBufferSize;
   215	    ackMessage.sendBufferSize = channel->config.sendBufferSize;
   216	    ackMessage.maxMessageSize = channel->config.localMaxMessageSize;
   217	    ackMessage.maxChunkCount = channel->config.localMaxChunkCount;
   218	
   219	    UA_TcpMessageHeader ackHeader;
   220	    ackHeader.messageTypeAndChunkType = UA_MESSAGETYPE_ACK + UA_CHUNKTYPE_FINAL;
   221	    ackHeader.messageSize = 8 + 20; /* ackHeader + ackMessage */
   222	
   223	    /* Encode and send the response */
   224	    UA_Byte *bufPos = ack_msg.data;
   225	    const UA_Byte *bufEnd = &ack_msg.data[ack_msg.length];
   226	    retval |= UA_encodeBinaryInternal(&ackHeader,
   227	                                      &UA_TRANSPORT[UA_TRANSPORT_TCPMESSAGEHEADER],
   228	                                      &bufPos, &bufEnd, NULL, NULL, NULL);
   229	    retval |= UA_encodeBinaryInternal(&ackMessage,
   230	                                      &UA_TRANSPORT[UA_TRANSPORT_TCPACKNOWLEDGEMESSAGE],
   231	                                      &bufPos, &bufEnd, NULL, NULL, NULL);
   232	    if(retval != UA_STATUSCODE_GOOD) {
   233	        cm->freeNetworkBuffer(cm, channel->connectionId, &ack_msg);
   234	        return retval;
   235	    }
   236	
   237	    ack_msg.length = ackHeader.messageSize;
   238	    retval = cm->sendWithConnection(cm, channel->connectionId, &UA_KEYVALUEMAP_NULL, &ack_msg);
   239	    if(retval == UA_STATUSCODE_GOOD)
   240	        channel->state = UA_SECURECHANNELSTATE_ACK_SENT;
   241	    return retval;
   242	}
