   244	/* OPN -> Open up/renew the securechannel */
   245	static UA_StatusCode
   246	processOPN(UA_Server *server, UA_SecureChannel *channel,
   247	           const UA_UInt32 requestId, const UA_ByteString *msg) {
   248	    UA_LOCK_ASSERT(&server->serviceMutex);
   249	
   250	    if(channel->state != UA_SECURECHANNELSTATE_ACK_SENT &&
   251	       channel->state != UA_SECURECHANNELSTATE_OPEN)
   252	        return UA_STATUSCODE_BADINTERNALERROR;
   253	    /* Decode the request */
   254	    UA_NodeId requestType;
   255	    UA_OpenSecureChannelRequest openSecureChannelRequest;
   256	    size_t offset = 0;
   257	    UA_StatusCode retval = UA_NodeId_decodeBinary(msg, &offset, &requestType);
   258	    if(retval != UA_STATUSCODE_GOOD) {
   259	        UA_NodeId_clear(&requestType);
   260	        UA_LOG_WARNING_CHANNEL(server->config.logging, channel,
   261	                               "Could not decode the NodeId. "
   262	                               "Closing the SecureChannel.");
   263	        UA_SecureChannel_shutdown(channel, UA_SHUTDOWNREASON_REJECT);
   264	        return retval;
   265	    }
   266	    retval = UA_decodeBinaryInternal(msg, &offset, &openSecureChannelRequest,
   267	                                     &UA_TYPES[UA_TYPES_OPENSECURECHANNELREQUEST], NULL);
   268	
   269	    /* Error occurred */
   270	    const UA_NodeId *opnRequestId =
   271	        &UA_TYPES[UA_TYPES_OPENSECURECHANNELREQUEST].binaryEncodingId;
   272	    if(retval != UA_STATUSCODE_GOOD || !UA_NodeId_equal(&requestType, opnRequestId)) {
   273	        UA_NodeId_clear(&requestType);
   274	        UA_OpenSecureChannelRequest_clear(&openSecureChannelRequest);
   275	        UA_LOG_WARNING_CHANNEL(server->config.logging, channel,
   276	                               "Could not decode the OPN message. "
   277	                               "Closing the SecureChannel.");
   278	        UA_SecureChannel_shutdown(channel, UA_SHUTDOWNREASON_REJECT);
   279	        return retval;
   280	    }
   281	    UA_NodeId_clear(&requestType);
   282	
   283	    /* Call the service */
   284	    UA_OpenSecureChannelResponse openScResponse;
   285	    UA_OpenSecureChannelResponse_init(&openScResponse);
   286	    Service_OpenSecureChannel(server, channel, &openSecureChannelRequest, &openScResponse);
   287	    UA_OpenSecureChannelRequest_clear(&openSecureChannelRequest);
   288	    if(openScResponse.responseHeader.serviceResult != UA_STATUSCODE_GOOD) {
   289	        UA_LOG_WARNING_CHANNEL(server->config.logging, channel,
   290	                               "Could not open a SecureChannel. "
   291	                               "Closing the connection.");
   292	        UA_SecureChannel_shutdown(channel, UA_SHUTDOWNREASON_REJECT);
   293	        return openScResponse.responseHeader.serviceResult;
   294	    }
   295	
   296	    /* Send the response */
   297	    retval = UA_SecureChannel_sendOPN(channel, requestId, &openScResponse,
   298	                                      &UA_TYPES[UA_TYPES_OPENSECURECHANNELRESPONSE]);
   299	    UA_OpenSecureChannelResponse_clear(&openScResponse);
   300	    if(retval != UA_STATUSCODE_GOOD) {
   301	        UA_LOG_WARNING_CHANNEL(server->config.logging, channel,
   302	                               "Could not send the OPN answer with error code %s",
   303	                               UA_StatusCode_name(retval));
   304	        UA_SecureChannel_shutdown(channel, UA_SHUTDOWNREASON_REJECT);
   305	    }
   306	
   307	    return retval;
   308	}
