   310	/* The responseHeader must have the requestHandle already set */
   311	UA_StatusCode
   312	sendResponse(UA_Server *server, UA_SecureChannel *channel, UA_UInt32 requestId,
   313	             UA_Response *response, const UA_DataType *responseType) {
   314	    if(!channel)
   315	        return UA_STATUSCODE_BADINTERNALERROR;
   316	
   317	    /* If the overall service call failed, answer with a ServiceFault */
   318	    if(response->responseHeader.serviceResult != UA_STATUSCODE_GOOD)
   319	        return sendServiceFault(server, channel, requestId,
   320	                                response->responseHeader.requestHandle,
   321	                                response->responseHeader.serviceResult);
   322	
   323	    /* Prepare the ResponseHeader */
   324	    UA_EventLoop *el = server->config.eventLoop;
   325	    response->responseHeader.timestamp = el->dateTime_now(el);
   326	
   327	    /* Start the message context */
   328	    UA_MessageContext mc;
   329	    UA_StatusCode retval = UA_MessageContext_begin(&mc, channel, requestId, UA_MESSAGETYPE_MSG);
   330	    if(retval != UA_STATUSCODE_GOOD)
   331	        return retval;
   332	
   333	    /* Assert's required for clang-analyzer */
   334	    UA_assert(mc.buf_pos == &mc.messageBuffer.data[UA_SECURECHANNEL_SYMMETRIC_HEADER_TOTALLENGTH]);
   335	    UA_assert(mc.buf_end <= &mc.messageBuffer.data[mc.messageBuffer.length]);
   336	
   337	    /* Encode the response type */
   338	    retval = UA_MessageContext_encode(&mc, &responseType->binaryEncodingId,
   339	                                      &UA_TYPES[UA_TYPES_NODEID]);
   340	    if(retval != UA_STATUSCODE_GOOD)
   341	        return retval;
   342	
   343	    /* Encode the response */
   344	    retval = UA_MessageContext_encode(&mc, response, responseType);
   345	    if(retval != UA_STATUSCODE_GOOD)
   346	        return retval;
   347	
   348	    /* Finish / send out */
   349	    return UA_MessageContext_finish(&mc);
   350	}
