   352	/* A Session is "bound" to a SecureChannel if it was created by the
   353	 * SecureChannel or if it was activated on it. A Session can only be bound to
   354	 * one SecureChannel. A Session can only be closed from the SecureChannel to
   355	 * which it is bound.
   356	 *
   357	 * Returns Good if the AuthenticationToken exists nowhere (for CTT). */
   358	UA_StatusCode
   359	getBoundSession(UA_Server *server, const UA_SecureChannel *channel,
   360	                const UA_NodeId *token, UA_Session **session) {
   361	    UA_LOCK_ASSERT(&server->serviceMutex);
   362	    UA_EventLoop *el = server->config.eventLoop;
   363	    UA_DateTime nowMonotonic = el->dateTime_nowMonotonic(el);
   364	
   365	    for(UA_Session *s = channel->sessions; s; s = s->next) {
   366	        if(!UA_NodeId_equal(token, &s->authenticationToken))
   367	            continue;
   368	
   369	        /* Has the session timed out? */
   370	        if(s->validTill < nowMonotonic)
   371	            return UA_STATUSCODE_BADSESSIONCLOSED;
   372	
   373	        /* Return the session */
   374	        *session = s;
   375	        return UA_STATUSCODE_GOOD;
   376	    }
   377	
   378	    /* Session exists on another SecureChannel */
   379	    UA_Session *tmpSession = getSessionByToken(server, token);
   380	    if(tmpSession) {
   381	#ifdef UA_ENABLE_DIAGNOSTICS
   382	        tmpSession->diagnostics.unauthorizedRequestCount++;
   383	#endif
   384	        return UA_STATUSCODE_BADSECURECHANNELIDINVALID;
   385	    }
   386	
   387	    /* The StatusCode indicates if the Session doesn't exist or whether it does
   388	     * not match to SecureChannel */
   389	    return UA_STATUSCODE_BADSESSIONIDINVALID;
   390	}
